                for (j = 0; j < KP.length; j++) { ds[KP[j] + 'History'][i - 1] = kp[KP[j]]; }
                ds.roundScores[i - 1] = r.score;
                ds.scoreHistory[i - 1] = r.score;
                rs = r;
            }
            ds.hardFail = rs.m.hard;
            var q = period - 1;
            ds.last = { roundScore: rs.score, hard: rs.m.hard };
            for (j = 0; j < KP.length; j++) { ds.last[KP[j]] = ds[KP[j] + 'History'][q]; }
            var score = this._composite(state);
            ds.performance = { overallScore: score };
            out.overallScore = score;
            out.score = score;
            out.roundScore = rs.score;
            for (j = 0; j < KP.length; j++) { out[KP[j]] = ds.last[KP[j]]; }
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _pol(a0, m) {
            var a = {};
            var j, g;
            for (j = 0; j < this.KEYS.length; j++) {
                g = this.KEYS[j];
                a[g] = (m >= this.START[g]) ? a0[g] : this.REF[g];
            }
            return a;
        }

        _ncdf(z) {
            var x = Math.abs(z);
            var t = 1.0 / (1.0 + 0.2316419 * x);
            var poly = t * (0.319381530 + t * (-0.356563782 + t * (1.781477937 + t * (-1.821255978 + t * 1.330274429))));
            var pdf = 0.3989422804014327 * Math.exp(-0.5 * x * x);
            var p = 1.0 - pdf * poly;
            return (z >= 0) ? p : 1.0 - p;
        }

        _loss(z) {
            return 0.3989422804014327 * Math.exp(-0.5 * z * z) - z * (1.0 - this._ncdf(z));
        }

        _psum(xs) {
            var t = 0.0, i;
            for (i = 0; i < xs.length; i++) { t = t + xs[i]; }
            return t;
        }

        _shares(a, m, stop) {
            var main = this.EVA[a.evaluacion1][0];
            var rp = this.REP[a.reparto1];
            var sh = {};
            var i;
            for (i = 0; i < this.KEYS_S.length; i++) { sh[this.KEYS_S[i]] = 0.0; }
            var excl = this.CON[a.contrato2][4] === 1;
            if (stop === 1 && m >= 13 && (this.CRI[a.crisis4][3] === 1 || this.CAR[a.cartera4][2] === 1)) { excl = true; }
            if (excl || a.reparto1 === 'unico') {
                sh[main] = 1.0;
                return { main: main, sh: sh };
            }
            if (a.reparto1 === 'rotar') {
                for (i = 0; i < 4; i++) { sh[this.KEYS_S[i]] = 0.25; }
                return { main: main, sh: sh };
            }
            var others = this.BACKUP_ORDER.filter(function(k) { return k !== main; });
            sh[main] = rp[0];
            if (a.reparto1 === 'dual') {
                sh[others[0]] = rp[1];
            } else {
                sh[others[0]] = rp[1];
                sh[others[1]] = rp[1];
            }
            if (stop === 1 && m >= 13 && a.cartera4 === 'homologar') {
                sh.segunda = sh[others[0]];
                sh[others[0]] = 0.0;
            }
            return { main: main, sh: sh };
        }

        _alt(sh, main) {
            var t = 0.0, i, k;
            for (i = 0; i < this.KEYS_S.length; i++) { k = this.KEYS_S[i]; if (k !== main) { t = t + sh[k]; } }
            return t;
        }

        _riseKept(a, sh, main) {
            var cr = a.crisis4;
            if (cr === 'viaje') { return this.CRI.viaje[2]; }
            var r = this.CON[a.contrato2][3];
            if (cr === 'activar') {
                r = r * ((this._alt(sh, main) >= this.C.ALT_MIN) ? this.CRI.activar[2] : this.ACT_SINGLE[2]);
            }
            return r;
        }

        _month(a0, m, stop) {
            var c = this.C;
            var a = this._pol(a0, m);
            var S0 = this._shares(a, m, stop);
            var main = S0.main, sh = S0.sh;
            var con = this.CON[a.contrato2], qa = this.QUA[a.calidad2], pg = this.PAG[a.pago3], sg = this.SEG[a.seguimiento3];
            var car = (stop === 1) ? this.CAR[a.cartera4] : this.CAR.mantener;
            var rp = this.REP[a.reparto1];
            var wpm = c.WPM, mu = c.MU, sd = c.SD, dm = wpm * mu;
            var out = { cost: 0.0, buy: 0.0, stock: 0.0, short: 0.0, dem: dm, defects: 0.0, defcost: 0.0, shortcost: 0.0,
                        orders: 0.0, mainshare: sh[main], price: 0.0 };
            var lbar = c.REVIEW, varl = 0.0, qbar = 0.0, cyc = 0.0, trans = 0.0, dbar = 0.0;
            var rise = 0.0;
            if (stop === 1 && m >= 13) { rise = c.RISE * this._riseKept(a, sh, main); }
            var i;
            for (i = 0; i < this.KEYS_S.length; i++) {
                var k = this.KEYS_S[i];
                var s = sh[k];
                if (s <= 0.0) { continue; }
                var sp = this.SUP[k];
                var p0 = sp[0], L = sp[1], sL = sp[2], S = sp[3], d0 = sp[4], moq = sp[5], tr = sp[6];
                var price = p0 * ((k !== 'distribuidor' && s < c.SMALL) ? 1.0 + c.SMALL_UP : 1.0) * sg[2];
                var sLk = sL * sg[0] * rp[3];
                var dk = d0 * sg[1] * qa[2];
                if (k === main) {
                    price = price * con[0] * car[0] * (1.0 + rise);
                    sLk = sLk * con[1] * car[1];
                    dk = dk * con[2];
                }
                var h = c.H * price;
                var D = c.YEAR_W * s * mu;
                var q = Math.sqrt(2.0 * D * S / h);
                if (q < moq * s * mu) { q = moq * s * mu; }
                if (q < c.LOTMIN) { q = c.LOTMIN; }
                var nord = s * dm / q;
                lbar += s * L;
                varl += (s * sLk) * (s * sLk);
                qbar += s * q;
                cyc += q / 2.0;
                if (tr === 1) { trans += s * mu * L; }
                dbar += s * dk;
                out.buy += s * dm * price;
                out.orders += nord;
                out.cost += nord * S;
            }
            var pavg = out.buy / dm;
            out.price = pavg;
            var sig = Math.sqrt(lbar * sd * sd + mu * mu * varl);
            var ss = car[3] * mu;
            var z = ss / sig;
            var cycles = dm / qbar;
            var short = cycles * sig * this._loss(z);
            if (short > dm) { short = dm; }
            var stocku = cyc + ss + trans;
            out.stock = stocku * pavg;
            out.cost += out.buy + out.stock * c.H / 12.0;
            var dfx = dm * dbar;
            var line = dfx * qa[0];
            out.defects = line;
            var dcost = line * c.DEF - (dfx - line) * pavg * qa[1];
            out.defcost = dcost;
            out.cost += dcost;
            out.short = short;
            out.shortcost = short * c.SHORT;
            out.cost += out.shortcost;
            var pay = out.buy * (((pg[0] === 1) ? 0.0 : c.OVER) - pg[1] + c.FIN * pg[2] / c.DAYS);
            out.cost += pay - out.buy * sg[4];
            out.cost += (qa[3] + pg[3] + sg[3]) / 12.0 + rp[2];
            if (stop === 1 && m >= 13 && con[4] === 1) {
                var unused = c.DROP * dm * sh[main];
                out.cost += unused * pavg;
            }
            if (stop === 1 && m === c.STOP_M) {
                var cut = (main === 'distribuidor') ? c.CUT_D : c.CUT;
                var gap = Math.max(0.0, cut * sh[main] * dm * c.GAP_M - ss);
                var cr = this.CRI[a0.crisis4];
                var cov = cr[0], prem = cr[1];
                if (a0.crisis4 === 'activar' && this._alt(sh, main) < c.ALT_MIN) {
                    cov = this.ACT_SINGLE[0]; prem = this.ACT_SINGLE[1];
                }
                var cv = cov * gap;
                var sh2 = gap - cv;
                out.cost += cv * pavg * prem + sh2 * c.SHORT;
                out.short += sh2;
                out.shortcost += sh2 * c.SHORT;
            }
            return out;
        }

        _event(dec, k) {
            var c = this.C;
            var self = this;
            var a = {};
            var j, m;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var oneoff = this.EVA[a.evaluacion1][1] + ((k >= 4) ? this.CAR[a.cartera4][4] : 0.0);
            var base = this._month(this.REF, 1, 1);
            var bcost = base.cost;
            var cost = 0.0, stock = 0.0, short = 0.0, dem = 0.0, buy = 0.0, shc = 0.0, dfc = 0.0, ms = 0.0;
            var stop = (k >= 4) ? 1 : 0;
            for (m = 1; m <= c.MONTHS; m++) {
                var r = this._month(a, m, stop);
                cost += r.cost; stock += r.stock; short += r.short; dem += r.dem; buy += r.buy;
                shc += r.shortcost; dfc += r.defcost; ms += r.mainshare;
            }
            var net = bcost * c.MONTHS - cost - oneoff;
            var fill = 1.0 - short / dem;
            var avg = stock / c.MONTHS;
            var turns = (buy / 2.0) / avg;
            var hard = 0;
            this.HARD.forEach(function(h2) { if (a[h2[0]] === h2[1] && k >= self.ROUND_OF[h2[0]]) { hard += 1; } });
            return { k: k, a: a, net: net, fill: fill, turns: turns, stock: avg, roturas: shc, defcost: dfc,
                     price: buy / dem, mainshare: ms / c.MONTHS, oneoff: oneoff, hard: hard };
        }

        _components(r) {
            var c = this.C;
            return [this._clamp((r.net - c.B_LO) / (c.B_HI - c.B_LO), 0, 1),
                    this._clamp((r.fill - c.F_LO) / (c.F_HI - c.F_LO), 0, 1),
                    this._clamp((r.turns - c.T_LO) / (c.T_HI - c.T_LO), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_B, c.W_F, c.W_T];
            var tw = 0, num = 0, i;
            for (i = 0; i < 3; i++) { tw += w[i]; num = num + w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
