        _fbKey(g, v) {
            var pfx = { evaluacion1: 'ev', reparto1: 're', contrato2: 'ct', calidad2: 'ca', pago3: 'pg', seguimiento3: 'sg', crisis4: 'cr', cartera4: 'cc' };
