                evaluacion1: ['costetotal', 'precio', 'habitual', 'puntos'],
                reparto1: ['dual', 'unico', 'tres', 'rotar'],
                contrato2: ['marco', 'pedido', 'tomaopaga', 'subasta'],
                calidad2: ['muestreo', 'total', 'confianza', 'certificado'],
                pago3: ['conciliar', 'prontopago', 'habitual', 'efectivo'],
                seguimiento3: ['cuadro', 'reunion', 'ninguno', 'penalizar'],
                crisis4: ['activar', 'aceptar', 'viaje', 'urgente'],
                cartera4: ['homologar', 'consolidar', 'mantener', 'recortar']
            };
            var keys = {
                fb_ev_costetotal: 1, fb_ev_precio: 1, fb_ev_habitual: 1, fb_ev_puntos: 1,
                fb_re_dual: 1, fb_re_unico: 1, fb_re_tres: 1, fb_re_rotar: 1,
                fb_ct_marco: 1, fb_ct_pedido: 1, fb_ct_tomaopaga: 1, fb_ct_subasta: 1,
                fb_ca_muestreo: 1, fb_ca_total: 1, fb_ca_confianza: 1, fb_ca_certificado: 1,
                fb_pg_conciliar: 1, fb_pg_prontopago: 1, fb_pg_habitual: 1, fb_pg_efectivo: 1,
                fb_sg_cuadro: 1, fb_sg_reunion: 1, fb_sg_ninguno: 1, fb_sg_penalizar: 1,
                fb_cr_activar: 1, fb_cr_aceptar: 1, fb_cr_viaje: 1, fb_cr_urgente: 1,
